head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[input > P > validateOnCheckMaxByteLength]<br/>입력값을 붙여넣기 할때 allowChar, ignoreChar 속성에 설정된 문자가 처리되는 시점을 설정합니다.",
    "validation" : [
        "미설정 시 입력값을 붙여넣기 시 maxByteLength 속성값에 맞게 초과된 문자를 제거 후 포커스가 해제될때 allowChar, ignoreChar 속성에서 입력이 허용되지 않은 문자를 제거합니다.",        
        "true 설정 시 입력값을 붙여넣기 시 allowChar, ignoreChar 속성에서 입력이 허용되지 않은 문자를 제거 후 maxByteLength 속성값에 맞게 초과된 문자를 제거합니다.",
        "false 설정 시 입력값을 붙여넣기 시 maxByteLength 속성값에 맞게 초과된 문자를 제거 후 포커스가 해제될때 allowChar, ignoreChar 속성에서 입력이 허용되지 않은 문자를 제거합니다.",                
        "datatype 이 숫자 유형이고 maxlength 가 설정됐을때 validateOnCheckMaxByteLength=true 이면 maxlength 길이에 맞게 자른 문자열을 붙여넣기 한 후 숫자, '+', '-', '.' 등이 아닌 문자는 제거됩니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.get_text = function(target) {    
    let rtn = '';
    let tagName = target.tagName

    if (tagName !== "INPUT") {
        rtn = target.textContent
        wf_body_bottom.getObj("scwin").setReturnValue("text : " + rtn);    
    }
    else {
        rtn = target.value
        wf_body_bottom.getObj("scwin").setReturnValue("text : " + rtn);   
    }    
}



scwin.target_onkeyup = function (e) {
    scwin.get_text(e.target);
};


scwin.btn_getText1_onclick = function (e) {
    scwin.get_text(target1.render);
};


scwin.btn_getText2_onclick = function (e) {
    scwin.get_text(target2.render);
};


scwin.btn_getText3_onclick = function (e) {
    scwin.get_text(target3.render);
};


scwin.btn_getText4_onclick = function (e) {
    scwin.get_text(target4.render);
};

scwin.btn_getText5_onclick = function (e) {
    scwin.get_text(target5.render);
};
